(() => {
  const W = window;
  W.__pose = {
    // Look DOWN at a world point from a given offset, matching the user's frame.
    at(tx, ty, tz, ox, oy, oz) {
      const t = W.__three, cam = t.camera, c = t.controls;
      cam.position.set(tx + ox, ty + oy, tz + oz);
      if (c) { c.target.set(tx, ty, tz); c.update(); } else { cam.lookAt(tx, ty, tz); }
      W.__store.getState().invalidate?.();
    },
    ops(tag) {
      const o = W.__wallOpacities ? W.__wallOpacities() : {};
      const keep = ['wall-int-bath2-hs','wall-int-mid-S','wall-int-hs-S','wall-int-hs-N','wall-int-shelter-LD'];
      console.log('OPACITY ' + tag + ' ' + keep.map((k) => k + '=' + (o[k] === undefined ? 'n/a' : o[k].toFixed(3))).join(' '));
    },
  };
})()
